import{_ as a,o as n,c as s,a2 as t,j as o,t as i,a as r}from"./chunks/framework.BXm-Zw-h.js";const k=JSON.parse('{"title":"Notebook Basics","description":"","frontmatter":{},"headers":[],"relativePath":"notebook-basics.md","filePath":"notebook-basics.md","lastUpdated":null}'),d={name:"notebook-basics.md"};function l(c,e,h,g,p,u){return n(),s("div",null,[e[2]||(e[2]=t(`<h1 id="Notebook-Basics" tabindex="-1">Notebook Basics <a class="header-anchor" href="#Notebook-Basics" aria-label="Permalink to &quot;Notebook Basics {#Notebook-Basics}&quot;">​</a></h1><h2 id="Cell-types" tabindex="-1">Cell types <a class="header-anchor" href="#Cell-types" aria-label="Permalink to &quot;Cell types {#Cell-types}&quot;">​</a></h2><p>There are four kinds:</p><ul><li><p><strong>Code cells</strong> evaluate Julia. The last expression&#39;s value renders below, along with stdout and any rich display (images, ECharts, tables, LaTeX).</p></li><li><p><strong>Markdown cells</strong> render GitHub-flavored markdown with LaTeX math and double-brace interpolation of Julia values. GFM tables work, as do <code>!!! note &quot;Title&quot;</code> admonitions; the category is free-form, so a notebook can coin its own.</p></li><li><p><strong>Web cells</strong> hold HTML, CSS and JS in their own panes, for building an interface that talks to Julia. See <a href="./frontend-extensions">Front-end Extensions</a>.</p></li><li><p><strong>Tool cells</strong> hold an <code>@tool name(...)</code> call, defining a tool the <a href="./agent">agent</a> can call. They are never swept up by an automatic run, so reopening a notebook does not re-fire one.</p></li></ul><p>The cell header shows a button for each kind the cell is <em>not</em> (<code>{·}</code> code, <code>&lt;/&gt;</code> web, <code>⌁</code> tool, <code>M↓</code> markdown). In command mode, <code>y</code> / <code>m</code> / <code>w</code> convert to code, markdown and web.</p><p>A code cell shows an always-on editor with tree-based Julia highlighting (CodeMirror 6 + the Lezer Julia grammar), the run button, timing, and state badge:</p><p><img class="slate-shot" src="https://github.com/kahliburke/KaimonSlate.jl/releases/download/docs-assets/editor-highlighting.png" alt=""></p><h2 id="Command-mode-vs.-edit-mode" tabindex="-1">Command mode vs. edit mode <a class="header-anchor" href="#Command-mode-vs.-edit-mode" aria-label="Permalink to &quot;Command mode vs. edit mode {#Command-mode-vs.-edit-mode}&quot;">​</a></h2><p>KaimonSlate uses a Jupyter-style two-mode model:</p><ul><li><p><strong>Command mode</strong> — the cell has an accent ring and single keys act on it.</p></li><li><p><strong>Edit mode</strong> — focus is inside the editor (green ring); <code>Esc</code> returns to command mode.</p></li></ul><p>Every key in the tables below is the <strong>default</strong> and every one of them can be changed — see <a href="/KaimonSlate.jl/dev/notebook-basics#Keyboard-shortcuts">Keyboard shortcuts</a> at the end of this page.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>↑</code>/<code>k</code>, <code>↓</code>/<code>j</code></td><td style="text-align:right;">move selection</td></tr><tr><td style="text-align:right;"><code>⇧↑</code> / <code>⇧↓</code> (also <code>⇧K</code> / <code>⇧J</code>)</td><td style="text-align:right;">extend the selection to the cell above / below</td></tr><tr><td style="text-align:right;"><code>⌥↑</code> / <code>⌥↓</code></td><td style="text-align:right;"><strong>move the cell</strong> up/down</td></tr><tr><td style="text-align:right;"><code>Esc</code></td><td style="text-align:right;">collapse a multi-selection back to one cell</td></tr><tr><td style="text-align:right;"><code>⏎</code></td><td style="text-align:right;">enter edit mode</td></tr><tr><td style="text-align:right;"><code>a</code> / <code>b</code></td><td style="text-align:right;">add cell above / below</td></tr><tr><td style="text-align:right;"><code>c</code> / <code>x</code> / <code>v</code></td><td style="text-align:right;">copy / cut / paste cell(s)</td></tr><tr><td style="text-align:right;"><code>m</code> / <code>y</code> / <code>w</code></td><td style="text-align:right;">to markdown / to code / to <a href="./frontend-extensions">web</a></td></tr><tr><td style="text-align:right;"><code>dd</code></td><td style="text-align:right;">delete cell</td></tr><tr><td style="text-align:right;"><code>⇧M</code></td><td style="text-align:right;">merge with the cell below</td></tr></tbody></table><p>Select several cells with shift-click (a range) or ⌘/Ctrl-click (toggle one), as well as the ⇧-arrow keys. Delete, cut, copy and the type-toggle keys then act on the whole selection, and a floating chip shows how many are selected. The cell clipboard is shared across notebook tabs.</p><p>You can also reorder with the mouse: drag the <strong>⠿</strong> grip in a cell&#39;s header and a drop line shows where it will land, or use the header&#39;s ↑/↓ buttons to move it one place.</p><p>In edit mode:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>⇧⏎</code></td><td style="text-align:right;">run (or commit a markdown/bind cell)</td></tr><tr><td style="text-align:right;"><code>⌘⇧⏎</code> / <code>Ctrl⇧⏎</code></td><td style="text-align:right;">run and open a fresh cell below</td></tr><tr><td style="text-align:right;"><code>⌘⇧-</code> / <code>Ctrl⇧-</code></td><td style="text-align:right;">split the cell at the cursor</td></tr><tr><td style="text-align:right;"><code>⇥</code></td><td style="text-align:right;">completion (Julia REPL completions + cell-local bindings)</td></tr><tr><td style="text-align:right;"><code>⌘⌥↑</code> / <code>⌘⌥↓</code></td><td style="text-align:right;">add a caret on the line above / below</td></tr><tr><td style="text-align:right;"><code>⌥</code>-click</td><td style="text-align:right;">add a caret at the click</td></tr><tr><td style="text-align:right;"><code>⌘D</code> / <code>CtrlD</code></td><td style="text-align:right;">select the word under the caret, then each next occurrence</td></tr></tbody></table><p>Extra carets type together. <code>Esc</code> drops back to a single caret, or clears a selection, and a second <code>Esc</code> returns to command mode. That holds under every keymap. Vim reaches it one rung later: <code>Esc</code> leaves insert or visual mode first, then collapses the carets, and only once there is a single bare caret does it hand the cell back to command mode.</p><p>Selecting a word also tints its other occurrences in that cell. Turn it off, or recolour it, under Settings → <em>Highlight matching words</em> and <em>Match highlight</em>.</p><p>Notebook-wide:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Key</th><th style="text-align:right;">Action</th></tr></thead><tbody><tr><td style="text-align:right;"><code>⌘↵</code></td><td style="text-align:right;">run stale cells</td></tr><tr><td style="text-align:right;"><code>⌘F</code> / <code>⌘⌥F</code></td><td style="text-align:right;">find across every cell / find and replace</td></tr><tr><td style="text-align:right;"><code>⌘G</code> / <code>⇧⌘G</code></td><td style="text-align:right;">next / previous match</td></tr><tr><td style="text-align:right;"><code>⌘K</code> / <code>⌘⇧K</code></td><td style="text-align:right;">command palette / docs search</td></tr><tr><td style="text-align:right;"><code>⌘⇧A</code></td><td style="text-align:right;">agent panel</td></tr><tr><td style="text-align:right;"><code>⌘⇧F</code></td><td style="text-align:right;">controls palette</td></tr><tr><td style="text-align:right;"><code>⌘⇧L</code></td><td style="text-align:right;">table of contents</td></tr><tr><td style="text-align:right;"><code>⌘⇧G</code></td><td style="text-align:right;">dependency graph</td></tr><tr><td style="text-align:right;"><code>⌘⇧S</code></td><td style="text-align:right;">scratchpad</td></tr><tr><td style="text-align:right;"><code>⌘Z</code> / <code>⌘⇧Z</code></td><td style="text-align:right;">undo / redo structural changes</td></tr></tbody></table><h2 id="Keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#Keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts {#Keyboard-shortcuts}&quot;">​</a></h2><p>Every shortcut above is a <strong>command</strong> with a stable name, and the chord that runs it is yours to change. <strong>Settings → Keyboard → Customise…</strong> opens the full list: search it, click a chord to re-record it, <code>✕</code> to remove one, <code>+</code> to add a second, <code>↺</code> to put a row back the way it came.</p><p>A whole <strong>keymap preset</strong> switches the lot at once, in the same Settings section:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Preset</th><th style="text-align:right;">What it follows</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>Slate</strong></td><td style="text-align:right;">the defaults above — Jupyter-style command mode, ⌘-chords for the panels</td></tr><tr><td style="text-align:right;"><strong>VS Code</strong></td><td style="text-align:right;">⌘⇧P palette, ⌘⇧O outline, ⌃↵ run cell, ⌥↵ run and insert below, ⌘⇧E files</td></tr><tr><td style="text-align:right;"><strong>Jupyter / Colab</strong></td><td style="text-align:right;">classic command mode verbatim — ⌃↵ run, ⇧↵ run and advance, <code>z</code> undo, <code>ii</code> interrupt, <code>00</code> restart</td></tr><tr><td style="text-align:right;"><strong>Vim-flavoured</strong></td><td style="text-align:right;">vim motions over the <em>cells</em> — <code>j</code>/<code>k</code>, <code>gg</code>/<code>⇧G</code>, <code>i</code>/<code>o</code>/<code>⇧O</code>, <code>dd</code>/<code>yy</code>/<code>p</code>, <code>u</code> and <code>⌃R</code></td></tr></tbody></table><p>A preset is a starting point, not a lock: anything you rebind on top of it is kept separately, so switching preset moves everything you <em>haven&#39;t</em> touched and leaves what you have.</p><p>Three things the panel does that are worth knowing about:</p><ul><li><p><strong>Sequences.</strong> A binding can be more than one keystroke — <code>dd</code>, <code>gg</code>, <code>⌘K Z</code>. Press the strokes in turn while recording and pause to save. When you type the first stroke of one, a chip at the bottom of the window shows what is armed.</p></li><li><p><strong>Reserved chords.</strong> A browser keeps a handful of combinations for itself — new tab, close window, the devtools — and a page never sees them. Those are refused outright rather than accepted and quietly broken. Ones the browser <em>will</em> give up (⌘S, ⌘P, ⌘F) are allowed with a note saying what they shadow. None of the four presets ships a chord from either group.</p></li><li><p><strong>Clashes are a question, not an outcome.</strong> Record a chord something else already uses and nothing is written: the panel names the command holding it and offers <strong>Reassign…</strong> (take it, then record a replacement for the one you displaced, right there), <strong>Take it</strong> (leave the other unbound), <strong>Keep both</strong> (flagged as a conflict on both rows), or <strong>Cancel</strong> — which changes nothing at all. Only a clash in a context the two actually <em>share</em> counts, so <code>b</code> in command mode and <code>b</code> in the editor are left alone.</p></li></ul><p>Shortcuts are stored per person rather than per notebook, in <code>keymap.json</code> under your Slate config directory — so they follow you between browsers, and you can read, hand-edit or check in the file. <strong>Export</strong> / <strong>Import</strong> move a keymap as JSON.</p><p>Text editing <em>inside</em> a cell — word motion, indentation, bracket matching, <code>⌘/</code> for comments — is a separate choice: <strong>Settings → Editing → Editor keymap</strong>, which is <code>default</code>, <code>vim</code> or <code>emacs</code>. Those bring complete binding sets of their own, and where one of them claims a chord Slate also uses, the editor keymap wins inside the editor. Consequently a row in the panel&#39;s <strong>Editor</strong> group adds a chord next to whatever that keymap already binds for the same action, rather than replacing it.</p><p>An <a href="./extensions">extension</a> that contributes a palette command gets a row here too, badged with the package that owns it, so its shortcut is as changeable as the built-in ones.</p><h3 id="Finding-across-the-notebook" tabindex="-1">Finding across the notebook <a class="header-anchor" href="#Finding-across-the-notebook" aria-label="Permalink to &quot;Finding across the notebook {#Finding-across-the-notebook}&quot;">​</a></h3><p><strong>⌘F</strong> opens one find bar for the whole document rather than a panel inside the focused cell — in a notebook what you are looking for is usually in a <em>different</em> cell. It walks every cell in order, counts the hits and steps between them across cell boundaries with <strong>⏎</strong> or <strong>⌘G</strong>. <strong>⌘⌥F</strong> opens the replace row as well; <strong>⌘⏎</strong> there replaces every match in the notebook.</p><p>The three switches on the bar are match case (<code>Aa</code>), whole word (<code>ab</code>) and regular expression (<code>.*</code>). Whole word is decided by character category rather than <code>\\b</code>, so it behaves sensibly for the Unicode names Julia encourages: searching <code>α</code> matches a standalone <code>α</code> and not the <code>α</code> inside <code>αβ</code>. In regex mode <code>$1</code>…<code>$9</code>, <code>$&amp;</code> and <code>$$</code> expand in the replacement; in plain mode a <code>$</code> stays a <code>$</code>.</p><p>Cells that have not been scrolled to yet still contribute to the count — their text comes from the last saved source. Stepping onto a match in a markdown or <code>@bind</code> cell opens that cell&#39;s source so the match can be shown.</p><p><strong>Replace All is a single action.</strong> It rewrites every match across the notebook in one step, which means one <strong>⌘Z</strong> puts it all back — the toast names what it undid — and the <a href="./history">timeline</a> gets one checkpoint labelled with the search and replacement, so you can also restore it later from <strong>☰ → 🕘 History</strong>. The rewritten cells are left stale rather than re-run: a text substitution decides what your code says, not when it should run.</p><p>Inside the <strong>Files</strong> tab&#39;s whole-file editor, ⌘F keeps CodeMirror&#39;s own single-document find panel, scoped to that one file.</p><h2 id="Running-cells" tabindex="-1">Running cells <a class="header-anchor" href="#Running-cells" aria-label="Permalink to &quot;Running cells {#Running-cells}&quot;">​</a></h2><p>Run a single cell with <strong>⇧⏎</strong>, or press <strong>⌘⏎</strong> (<strong>Ctrl⏎</strong>) to recompute every stale cell. The same action is in the command palette as <em>Run stale cells</em>. The kernel dot in the top bar breathes while a computation is in flight.</p><h3 id="Stopping-a-run" tabindex="-1">Stopping a run <a class="header-anchor" href="#Stopping-a-run" aria-label="Permalink to &quot;Stopping a run {#Stopping-a-run}&quot;">​</a></h3><p>A run in flight can be interrupted. That leaves the namespace intact, so everything computed so far is still there. <strong>⟲ Restart worker</strong> is the heavier option: it discards the run and the namespace with it.</p><h3 id="When-a-run-gets-stuck" tabindex="-1">When a run gets stuck <a class="header-anchor" href="#When-a-run-gets-stuck" aria-label="Permalink to &quot;When a run gets stuck {#When-a-run-gets-stuck}&quot;">​</a></h3><p>A supervisor sweeps every few seconds and raises a badge in the top bar when something looks wrong: amber for a warning, red for something critical. Clicking it opens a panel naming each alert, a stalled kernel or a runaway loop, with the recovery action for that alert (stop the run, or restart the worker).</p><h2 id="The-scratchpad" tabindex="-1">The scratchpad <a class="header-anchor" href="#The-scratchpad" aria-label="Permalink to &quot;The scratchpad {#The-scratchpad}&quot;">​</a></h2><p><strong>☰ → 🧪 Scratchpad</strong> (⌘⇧S) opens a panel where you can run Julia in the notebook&#39;s own kernel without creating a cell or touching the <code>.jl</code>. Results stream in with a timestamp, 🧹 clears them, and the 🧪 pill in the top bar lights up while something is running there.</p><p>It is the place for a quick check that is not part of the document. The <a href="./agent">agent</a>&#39;s <code>slate_eval</code> runs in the same scratchpad.</p><h2 id="Opening-a-cold-notebook" tabindex="-1">Opening a cold notebook <a class="header-anchor" href="#Opening-a-cold-notebook" aria-label="Permalink to &quot;Opening a cold notebook {#Opening-a-cold-notebook}&quot;">​</a></h2><p>The first open of a notebook whose packages are not yet precompiled shows a banner reading <em>Precompiling k/N · &lt;package&gt;</em>, with elapsed time and a collapsible build log. This is one-time; later opens are fast, and you can keep editing while it runs.</p><p>Installing a package mid-session is different: that shows a blocking overlay, because the notebook is paused while its environment resolves and precompiles.</p><p>A notebook can also open <strong>inactive</strong>, showing its stored results with no worker behind it. See <a href="/KaimonSlate.jl/dev/getting-started#The-front-page">the front page</a>.</p><h2 id="Quiet-cells" tabindex="-1">Quiet cells <a class="header-anchor" href="#Quiet-cells" aria-label="Permalink to &quot;Quiet cells {#Quiet-cells}&quot;">​</a></h2><p>A code cell whose last non-comment line ends in <code>;</code> suppresses display of the value (stdout and explicit <code>display()</code> still show) — handy for setup cells.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">big </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> rand</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># no 1000×1000 dump</span></span></code></pre></div><h2 id="Markdown-interpolation" tabindex="-1">Markdown interpolation <a class="header-anchor" href="#Markdown-interpolation" aria-label="Permalink to &quot;Markdown interpolation {#Markdown-interpolation}&quot;">​</a></h2><p>Inside a markdown cell, a double-brace <code>expr</code> block splices a Julia value into the rendered output:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Mean: {{ round(mean(data); digits=2) }}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ echart(spec) }}          &lt;!-- an interactive chart --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ slate_table(df) }}       &lt;!-- an interactive table --&gt;</span></span></code></pre></div><p>Scalars render inline; images, charts, and tables render as blocks. Interpolation works inside math (<code>$…$</code>) too.</p><p><img class="slate-shot" src="https://github.com/kahliburke/KaimonSlate.jl/releases/download/docs-assets/markdown.png" alt=""></p><h2 id="Images-and-clips" tabindex="-1">Images and clips <a class="header-anchor" href="#Images-and-clips" aria-label="Permalink to &quot;Images and clips {#Images-and-clips}&quot;">​</a></h2><p>An image alone in its paragraph is treated as a figure and centred; one sitting inside a run of prose stays inline where you put it. An attribute block directly after the image (no space, as in Pandoc/Quarto) overrides how it is drawn:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">A phase portrait</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">plot.png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">){width=300}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Logo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">logo.svg</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">){width=40% align=right}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">Detail</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">detail.png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">){.zoomable #fig-detail title=&quot;click to enlarge&quot;}</span></span></code></pre></div>`,60)),o("p",null,[e[0]||(e[0]=t("<code>width</code>/<code>height</code> take a bare number as pixels (<code>300</code> → <code>300px</code>) or any CSS length or percentage; <code>align</code> is <code>left</code>, <code>right</code>, or <code>center</code>; <code>.name</code> adds a class, <code>#name</code> sets an id. The same block works on a <code>&lt;video&gt;</code> or <code>&lt;audio&gt;</code> you dropped into the cell, and on an interpolated ",24)),o("code",null,i(),1),e[1]||(e[1]=r(" image. Sizes carry into the HTML export and the PDF; unrecognised keys are dropped rather than emitted.",-1))]),e[3]||(e[3]=t('<h2 id="completion" tabindex="-1">Completion <a class="header-anchor" href="#completion" aria-label="Permalink to &quot;Completion&quot;">​</a></h2><p>Tab-completion uses Julia&#39;s REPL completions against the live kernel <strong>plus</strong> the cell&#39;s own local bindings (assignments, loop/comprehension variables, function parameters) so names complete even before the cell has run. The popup carries a docstring preview, and method completions insert tab-through argument placeholders. LaTeX/emoji shortcuts work — type <code>\\pi</code>⇥ → <code>π</code>.</p><p><img class="slate-shot" src="https://github.com/kahliburke/KaimonSlate.jl/releases/download/docs-assets/completion.png" alt=""></p><h2 id="Renaming-cells" tabindex="-1">Renaming cells <a class="header-anchor" href="#Renaming-cells" aria-label="Permalink to &quot;Renaming cells {#Renaming-cells}&quot;">​</a></h2><p>Cell ids are header-safe labels. Double-click a cell&#39;s id to rename it; renames are tracked as renames in <a href="./history">history</a>, and dependencies (which are by id) are rebuilt.</p>',5))])}const b=a(d,[["render",l]]);export{k as __pageData,b as default};
